#!/bin/bash
# Hash first 64MB + last 64MB on both sides
ESX_HASH=$(sshpass -f /run/pegaprox-v2p-t1-copy ssh -o StrictHostKeyChecking=accept-new -o ServerAliveInterval=30 -o ServerAliveCountMax=5 -o HostKeyAlgorithms=+ssh-rsa,ssh-ed25519,ecdsa-sha2-nistp256 -o PubkeyAcceptedAlgorithms=+ssh-rsa,ssh-ed25519 -o KexAlgorithms=+diffie-hellman-group14-sha1,diffie-hellman-group14-sha256,ecdh-sha2-nistp256 -o PreferredAuthentications=keyboard-interactive,password  root@esx1.lab '{ dd if=/vmfs/volumes/ds1/app01/app01-flat.vmdk bs=1M count=64 2>/dev/null; dd if=/vmfs/volumes/ds1/app01/app01-flat.vmdk bs=1M skip=1987 count=64 2>/dev/null; }' | xxhsum 2>/dev/null | awk '{print $1}')

PVE_HASH=$({
  dd if=/dev/local-lvm/vm-120-disk-0 bs=1M count=64 2>/dev/null;
  dd if=/dev/local-lvm/vm-120-disk-0 bs=1M skip=$(((2150629376 / 1048576) - 64)) count=64 2>/dev/null;
} | xxhsum 2>/dev/null | awk '{print $1}')

if [ "$ESX_HASH" = "$PVE_HASH" ] && [ -n "$ESX_HASH" ]; then
  echo "MATCH:$ESX_HASH"
else
  echo "MISMATCH:ESX=$ESX_HASH PVE=$PVE_HASH"
fi
V2P_NODE_SCRIPT

